/** Every icon id in the pack. */
export const ICON_NAMES = Object.keys(ICONS) as AhosIconName[];

/** Standard `process.env.NODE_ENV` probe without depending on @types/node. */
const isDev = (globalThis as { process?: { env?: Record<string, string | undefined> } }).process?.env?.NODE_ENV !== 'production';

/**
 * Dynamic-name renderer: `<AhosGlyph name="nav/oil" variant="gold" />`.
 * Prefer the named exports from `./components` when the name is static — they
 * tree-shake, this dispatcher does not.
 */
export const AhosGlyph = ({
  name,
  variant = 'outline',
  ...rest
}: { name: AhosIconName; variant?: AhosIconVariant | 'color' } & Record<string, unknown>) => {
  const entry = ICONS[name] as Record<string, ComponentType<Record<string, unknown>>> | undefined;
  if (!entry) {
    if (isDev) {
      console.warn(`[AhosIcon] unknown icon name: ${name}`);
    }
    return null;
  }
  const Component = entry[variant] ?? entry.outline;
  return <Component {...rest} />;
};
